/* Lot 93: registered values with the Lot 93 functions computed in the reader sheet (generated by scripts/lot93_mathgen.py; expectations from lot93_mathmodel.py). */

#include "../../framework/unity.h"
#include <string.h>
#include <stdio.h>
#include "wf_sitecss.h"

static wf_site_t g_d;
static char g_html[4096], g_t[256];

static void prep(const char *css) {
    snprintf(g_html, sizeof(g_html), "<html><head><style>%s</style></head><body>"
             "<div id=o><p id=i>i</p></div><p id=q>q</p></body></html>", css);
    TEST_ASSERT_EQUAL(0, wf_site_prepare(&g_d, g_html, (int)strlen(g_html)));
    TEST_ASSERT_EQUAL(1, g_d.nprops);
}

static const char *nv(const char *id) {
    int i;
    for (i = 0; i < g_d.nnodes; i++)
        if (!strcmp(g_d.node[i].id, id)) { const char *v = wf_site_node_var(&g_d, i, "--p"); return v ? v : "(none)"; }
    return "(no node)";
}

static const char *tail(void) {
    const char *s;
    wf_site_props_text(&g_d, g_t, (int)sizeof(g_t));
    s = strstr(g_t, " simplified ");
    return s ? s : "";
}

static void test_l93_sheet_0(void) {
    prep("@property --p { syntax: '<time>'; inherits: false; initial-value: 1s } #o { --p: hypot(17%*.4*-1241.7298,+13.48598%) } #i { --p: sqrt(4.44 *37.330/ infinity + 5.8320 /17) }");
    TEST_ASSERT_EQUAL_STRING("1s", nv("o"));
    TEST_ASSERT_EQUAL_STRING("1s", nv("i"));
    TEST_ASSERT_EQUAL_STRING("1s", nv("q"));
    TEST_ASSERT_EQUAL_STRING("", tail());
}

